The Master Theorem solves divide-and-conquer recurrences of the form:

**T(n) = a·T(n/b) + f(n)**  where a ≥ 1, b > 1

### Proof via Recursion Tree

Construct a tree of depth L = log_b n:

| Level | # Nodes | Cost per node     | Level total cost |
|-------|---------|-------------------|------------------|
| 0     | 1       | f(n)              | f(n)             |
| 1     | a       | f(n/b)            | a·f(n/b)         |
| 2     | a²      | f(n/b²)           | a²·f(n/b²)       |
| …     | …       | …                 | …                |
| i     | a^i     | f(n/b^i)          | a^i·f(n/b^i)     |
| L     | a^L     | Θ(1)              | Θ(n^{log_b a})   |

Total work: **T(n) = Σ_{i=0}^{L-1} a^i·f(n/b^i) + Θ(n^{log_b a})** where L = log_b n.

The number of leaves is a^{log_b n} = n^{log_b a} = n^c where **c = log_b a**.

Define c = log_b a. The three cases compare f(n) with n^c:

**Case 1** — f(n) = O(n^{c-ε}) for ε > 0:
The geometric series converges and the leaf term dominates.
→ **T(n) = Θ(n^c)**

**Case 2** — f(n) = Θ(n^c):
Every level contributes Θ(n^c) work, and there are log_b n levels.
→ **T(n) = Θ(n^c log n)**

**Case 3** — f(n) = Ω(n^{c+ε}) for ε > 0, and a·f(n/b) ≤ k·f(n) for k < 1:
The root term dominates the series.
→ **T(n) = Θ(f(n))**

### Implementation

```go
// master-theorem: T(n) = a·T(n/b) + f(n)
// Classifies recurrences and applies to Mergesort & Strassen.

package main

import (
    "fmt"
    "math"
)

func logBase(base, x float64) float64 {
    return math.Log(x) / math.Log(base)
}

// MasterCase classifies and returns the closed-form Θ expression.
func MasterCase(a, b int, p float64) (int, float64, float64, string) {
    c := logBase(float64(b), float64(a))
    const eps = 1e-9
    switch {
    case p < c-eps:
        return 1, c, p, fmt.Sprintf("Θ(n^{%.4f})", c)
    case math.Abs(p-c) <= eps:
        return 2, c, p, fmt.Sprintf("Θ(n^{%.4f} · log n)", c)
    default:
        return 3, c, p, fmt.Sprintf("Θ(n^{%.4f})", p)
    }
}

// RecursionTreeSum computes the recurrence numerically.
func RecursionTreeSum(a, b int, p float64, n int) (total float64, levels int, leafTerm float64, levelCosts []float64) {
    c := logBase(float64(b), float64(a))
    L := int(math.Round(logBase(float64(b), float64(n))))
    levelCosts = make([]float64, L)
    for i := 0; i < L; i++ {
        ni := float64(n) / math.Pow(float64(b), float64(i))
        levelCosts[i] = math.Pow(float64(a), float64(i)) * math.Pow(ni, p)
        total += levelCosts[i]
    }
    leafTerm = math.Pow(float64(n), c)
    total += leafTerm
    return
}
```

### Application: Mergesort — T(n) = 2·T(n/2) + Θ(n)

- a = 2, b = 2 → c = log₂(2) = 1
- f(n) = n → p = 1 = c → **Case 2**

```go
func Mergesort(arr []int) []int {
    if len(arr) <= 1 {
        return arr
    }
    mid := len(arr) / 2
    left := Mergesort(arr[:mid])
    right := Mergesort(arr[mid:])
    return merge(left, right)
}

func merge(a, b []int) []int {
    res := make([]int, 0, len(a)+len(b))
    i, j := 0, 0
    for i < len(a) && j < len(b) {
        if a[i] <= b[j] {
            res = append(res, a[i]); i++
        } else {
            res = append(res, b[j]); j++
        }
    }
    res = append(res, a[i:]...)
    res = append(res, b[j:]...)
    return res
}
```
→ **T(n) = Θ(n log n)** ✓

### Application: Strassen — T(n) = 7·T(n/2) + Θ(n²)

- a = 7, b = 2 → c = log₂(7) ≈ 2.807
- f(n) = n² → p = 2 < c-ε → **Case 1**

```go
func Strassen(A, B [][]int) [][]int {
    n := len(A)
    if n == 1 {
        return [][]int{{A[0][0] * B[0][0]}}
    }
    if n <= 64 { return naiveMul(A, B) }

    k := n / 2
    A11, A12, A21, A22 := partition(A, k)
    B11, B12, B21, B22 := partition(B, k)

    M1 := Strassen(add(A11, A22), add(B11, B22))
    M2 := Strassen(add(A21, A22), B11)
    M3 := Strassen(A11, sub(B12, B22))
    M4 := Strassen(A22, sub(B21, B11))
    M5 := Strassen(add(A11, A12), B22)
    M6 := Strassen(sub(A21, A11), add(B11, B12))
    M7 := Strassen(sub(A12, A22), add(B21, B22))

    C11 := add(sub(add(M1, M4), M5), M7)
    C12 := add(M3, M5)
    C21 := add(M2, M4)
    C22 := add(sub(add(M1, M3), M2), M6)

    return assemble(C11, C12, C21, C22)
}
```
→ **T(n) = Θ(n^{log₂ 7}) ≈ Θ(n^{2.807})** ✓

