// TestForemanTick90_GC verifies tickers are GC-able in Go 1.23+.
func TestForemanTick90_GC(t *testing.T) {
	if AsynctimerChan.Value() == "1" {
		t.Skip("skipping GC test with asynctimerchan=1")
	}

	// Create and drop many tickers, then verify GC reclaims them.
	const N = 1000
	var stats runtime.MemStats
	runtime.GC()
	runtime.GC()
	runtime.GC()
	runtime.ReadMemStats(&stats)
	before := int64(stats.Mallocs - stats.Frees)

	for range N {
		_ = NewTicker(Hour)
	}

	runtime.GC()
	runtime.GC()
	runtime.GC()
	runtime.ReadMemStats(&stats)
	after := int64(stats.Mallocs - stats.Frees)

	inuse := after - before
	if inuse >= N {
		t.Errorf("NewTicker allocations not GC'ed: %d remaining (of %d)", inuse, N)
	}
}

// TestForemanTick90_TickGC verifies Tick's underlying ticker is GC-able.
func TestForemanTick90_TickGC(t *testing.T) {
	if AsynctimerChan.Value() == "1" {
		t.Skip("skipping GC test with asynctimerchan=1")
	}

	const N = 1000
	var stats runtime.MemStats
	runtime.GC()
	runtime.GC()
	runtime.GC()
	runtime.ReadMemStats(&stats)
	before := int64(stats.Mallocs - stats.Frees)

	for range N {
		_ = Tick(Hour)
	}

	runtime.GC()
	runtime.GC()
	runtime.GC()
	runtime.ReadMemStats(&stats)
	after := int64(stats.Mallocs - stats.Frees)

	inuse := after - before
	if inuse >= N {
		t.Errorf("Tick allocations not GC'ed: %d remaining (of %d)", inuse, N)
	}
}

// TestForemanTick90_ConcurrentStopReset verifies concurrent Stop/Reset
// does not cause data races or deadlocks.
func TestForemanTick90_ConcurrentStopReset(t *testing.T) {
	t.Parallel()
	tk := NewTicker(10 * Millisecond)
	var wg sync.WaitGroup
	for range 10 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 20 {
				tk.Reset(10 * Millisecond)
				tk.Stop()
				// Drain
				select {
				case <-tk.C:
				default:
				}
			}
		}()
	}
	wg.Wait()
}
