The validator is implemented in `/home/kara/serde_json_validator.py` — a single-file Python 3.11+ JSON Schema validator. It recursively walks the instance against the schema keywords, building human-readable error paths like `$.address.zip`.

**Core algorithm** — a recursive `validate()` function:

```python
def validate(instance, schema, root_schema=None, path="$"):
    errors = []
    # 1. Resolve $ref first (with merge of sibling keywords)
    if "$ref" in schema:
        resolved = _resolve_ref(schema["$ref"], root_schema)
        merged = {**resolved, **{k: v for k, v in schema.items() if k != "$ref"}}
        return validate(instance, merged, root_schema, path)

    # 2. Type checking (supports union types via list)
    if "type" in schema:
        types = schema["type"] if isinstance(schema["type"], list) else [schema["type"]]
        if not any(_type_check(instance, t) for t in types):
            errors.append(f"{path}: expected type {types!r}...")

    # 3. Enum
    if "enum" in schema and instance not in schema["enum"]:
        errors.append(f"{path}: {instance!r} not in enum {schema['enum']!r}")

    # 4. Numeric bounds
    if isinstance(instance, (int, float)) and not isinstance(instance, bool):
        if "minimum" in schema and instance < schema["minimum"]:
            errors.append(f"{path}: {instance!r} < minimum {schema['minimum']!r}")
        if "maximum" in schema and instance > schema["maximum"]:
            errors.append(f"{path}: {instance!r} > maximum {schema['maximum']!r}")

    # 5. String validators (pattern, minLength, maxLength)
    if isinstance(instance, str):
        if "minLength" in schema and len(instance) < schema["minLength"]: ...
        if "maxLength" in schema and len(instance) > schema["maxLength"]: ...
        if "pattern" in schema:
            if not re.search(schema["pattern"], instance): ...

    # 6. Object: required, properties, additionalProperties
    if isinstance(instance, dict):
        for key in schema.get("required", []):
            if key not in instance:
                errors.append(f"{path}.{key}: missing required property")
        for key, prop_schema in schema.get("properties", {}).items():
            if key in instance:
                errors.extend(validate(instance[key], prop_schema, ...))
        # additionalProperties as boolean or schema
        ...

    # 7. Array items
    if isinstance(instance, list) and "items" in schema:
        ...

    # 8. Composition: anyOf/allOf/oneOf
    if "anyOf" in schema:
        # succeeds if at least one subschema produces no errors
        if not any(len(e) == 0 for e in sub_errors):
            errors.append(f"{path}: does not match any schema in anyOf...")
    if "allOf" in schema:
        for i, subschema in enumerate(schema["allOf"]):
            if errs := validate(instance, subschema, ...):
                errors.append(f"{path}: allOf[{i}] failed...")
    if "oneOf" in schema:
        # succeeds if exactly one subschema matches
        ...

    return errors
```

**Error paths** follow JSON Pointer convention: `$.name`, `$.address.zip`, `$.tags[0]`, `$.a.b[0].c`.

