The pipeline implements the **submit → queue → solve → discover → verify** flow as a thread-safe Go struct with proper state transitions. Each tick moves through statuses: `submitted` → `solved` → `verified`.

```go
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"sync"
	"time"
)

type Tick struct {
	ID          string     `json:"id"`
	Title       string     `json:"title"`
	Description string     `json:"description"`
	Status      string     `json:"status"`
	CreatedAt   time.Time  `json:"created_at"`
	SolvedAt    *time.Time `json:"solved_at,omitempty"`
	Solution    string     `json:"solution,omitempty"`
	Resolution  string     `json:"resolution,omitempty"`
}

type Pipeline struct {
	mu     sync.Mutex
	queue  []*Tick
	done   []*Tick
	nextID int
}

func (p *Pipeline) Submit(title, description string) *Tick {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.nextID++
	tick := &Tick{
		ID:          fmt.Sprintf("TICK-%03d", p.nextID),
		Title:       title,
		Description: description,
		Status:      "submitted",
		CreatedAt:   time.Now(),
	}
	p.queue = append(p.queue, tick)
	return tick
}

func (p *Pipeline) Queue() []*Tick {
	p.mu.Lock()
	defer p.mu.Unlock()
	result := make([]*Tick, len(p.queue))
	copy(result, p.queue)
	return result
}

func (p *Pipeline) Solve() (*Tick, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if len(p.queue) == 0 {
		return nil, fmt.Errorf("queue is empty, nothing to solve")
	}
	tick := p.queue[0]
	p.queue = p.queue[1:]
	now := time.Now()
	tick.SolvedAt = &now
	tick.Status = "solved"
	tick.Solution = fmt.Sprintf("Solution for %s: %s", tick.Title, tick.Description)
	return tick, nil
}

func (p *Pipeline) Discover() []string {
	p.mu.Lock()
	defer p.mu.Unlock()
	var insights []string
	for _, tick := range p.done {
		if tick.Status == "solved" {
			insights = append(insights,
				fmt.Sprintf("Discovered: %s was solved at %s", tick.ID, tick.SolvedAt.Format(time.RFC3339)))
		}
		if tick.Status == "verified" {
			insights = append(insights,
				fmt.Sprintf("Verified: %s passed all checks", tick.ID))
		}
	}
	return insights
}

func (p *Pipeline) Verify(tick *Tick) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if tick.Status != "solved" {
		return fmt.Errorf("tick %s is not in solved state (status: %s)", tick.ID, tick.Status)
	}
	if tick.Solution == "" {
		return fmt.Errorf("tick %s has no solution to verify", tick.ID)
	}
	if len(tick.Solution) < 10 {
		return fmt.Errorf("tick %s solution is too short to be valid", tick.ID)
	}
	tick.Status = "verified"
	tick.Resolution = "PASS"
	p.done = append(p.done, tick)
	return nil
}
```

**Key design decisions:**
- **Mutex-guarded state** for safe concurrent access across pipeline stages
- **Status state machine** prevents illegal transitions (e.g., verifying an unsolved tick)
- **Queue as slice** with FIFO dequeue semantics
- **Discover scans done tickets** to report both solved and verified insights

