package main

import (
	"fmt"
	"math"
)

// isPrime checks if a number is prime.
func isPrime(n int) bool {
	if n < 2 {
		return false
	}
	if n == 2 {
		return true
	}
	if n%2 == 0 {
		return false
	}
	for i := 3; i*i <= n; i += 2 {
		if n%i == 0 {
			return false
		}
	}
	return true
}

func main() {
	count, sum := 0, 0
	for n := 2; count < 10; n++ {
		if isPrime(n) {
			sum += n
			count++
		}
	}
	fmt.Printf("Sum of first 10 primes: %d\n", sum) // Output: 129
}
