The **off-by-one-self-test** problem demonstrates three classic off-by-one errors in Go and provides self-tests that catch them:

### Bug 1: Loop bound — `<=` instead of `<`

```go
// Bug: loop accesses nums[len(nums)], which is out of bounds
func Sum(nums []int) int {
    total := 0
    for i := 0; i <= len(nums); i++ {  // should be i < len(nums)
        total += nums[i]
    }
    return total
}

// Fix
func SumCorrect(nums []int) int {
    total := 0
    for i := 0; i < len(nums); i++ {
        total += nums[i]
    }
    return total
}
```

### Bug 2: Index access — `len(nums)` instead of `len(nums)-1`

```go
// Bug: index len(nums) is always out of bounds
func Last(nums []int) int {
    return nums[len(nums)]  // should be nums[len(nums)-1]
}

// Fix
func LastCorrect(nums []int) int {
    return nums[len(nums)-1]
}
```

### Bug 3: Slice upper bound — inclusive instead of exclusive

```go
// Bug: end+1 makes the upper bound inclusive, which is one past the correct value
func Subslice(nums []int, start, end int) []int {
    return nums[start : end+1]  // should be nums[start:end]
}

// Fix
func SubsliceCorrect(nums []int, start, end int) []int {
    return nums[start:end]
}
```

### Self-test (detects all three bugs)

```go
func TestSum(t *testing.T) {
    nums := []int{1, 2, 3}
    defer func() {
        if r := recover(); r != nil {
            t.Logf("Sum panicked with off-by-one: %v", r)
        } else {
            t.Error("Sum should have panicked — i <= len(nums) is out of bounds")
        }
    }()
    Sum(nums)
}

func TestLast(t *testing.T) {
    nums := []int{10, 20, 30}
    defer func() {
        if r := recover(); r != nil {
            t.Logf("Last panicked with off-by-one: %v", r)
        } else {
            t.Error("Last should have panicked — len(nums) is out of bounds")
        }
    }()
    Last(nums)
}

func TestSubslice(t *testing.T) {
    nums := []int{1, 2, 3, 4, 5}
    result := Subslice(nums, 1, 4)  // end = len(nums)-1 → end+1 = len(nums) → slice too large
    if len(result) != 3 {
        t.Errorf("Subslice returned %d elements, want 3 — off-by-one: end is inclusive", len(result))
    }
}
```

