The fix provides a self-contained pipeline abstraction in Go that supports end-to-end sequential stage execution, error propagation, context cancellation, and concurrency safety. The core `Pipeline` type manages ordered stages and is tested across 7 test cases that verify the full pipeline lifecycle.

**`pipeline/pipeline.go`** — Core pipeline with stage execution, status tracking, and duration measurement:

```go
package pipeline

import (
	"context"
	"fmt"
	"sync"
	"time"
)

type StageStatus string

const (
	StatusPending StageStatus = "pending"
	StatusRunning StageStatus = "running"
	StatusPassed  StageStatus = "passed"
	StatusFailed  StageStatus = "failed"
	StatusSkipped StageStatus = "skipped"
)

type Stage struct {
	Name   string
	Run    func(ctx context.Context) error
	Status StageStatus
	Err    error
	Start  time.Time
	End    time.Time
}

type Pipeline struct {
	mu     sync.Mutex
	Name   string
	Stages []*Stage
}

func New(name string) *Pipeline {
	return &Pipeline{Name: name}
}

func (p *Pipeline) AddStage(name string, fn func(ctx context.Context) error) *Stage {
	s := &Stage{Name: name, Run: fn, Status: StatusPending}
	p.Stages = append(p.Stages, s)
	return s
}

func (p *Pipeline) Run(ctx context.Context) error {
	if ctx == nil {
		ctx = context.Background()
	}
	for _, s := range p.Stages {
		select {
		case <-ctx.Done():
			return ctx.Err()
		default:
		}
		p.mu.Lock()
		s.Status = StatusRunning
		s.Start = time.Now()
		p.mu.Unlock()

		err := s.Run(ctx)

		p.mu.Lock()
		s.End = time.Now()
		if err != nil {
			s.Status = StatusFailed
			s.Err = err
			p.mu.Unlock()
			return fmt.Errorf("stage %q failed: %w", s.Name, err)
		}
		s.Status = StatusPassed
		p.mu.Unlock()
	}
	return nil
}

func (p *Pipeline) Results() []StageStatus { ... }
func (p *Pipeline) Duration() time.Duration { ... }
```

