func TestTick180_Buggy(t *testing.T) {
    ticker := time.NewTicker(time.Millisecond)
    defer ticker.Stop()

    count := 0
    for count < 180 {          // runs 180 times: 0..179 ✓
        <-ticker.C
        count++
    }

    want := 181                 // BUG: should be 180
    if count != want {
        t.Errorf("got %d ticks, want %d", count, want)
    }
}
```

