The engine is implemented in a single package `mvcc` with two files:

### `/home/kara/mvcc/mvcc.go` — Core MVCC Engine

```go
package mvcc

import (
	"errors"
	"sync"
)

var (
	ErrWriteConflict = errors.New("mvcc: write-write conflict detected, transaction aborted")
	ErrAborted       = errors.New("mvcc: transaction has been aborted")
	ErrCommitted     = errors.New("mvcc: transaction has already been committed")
	ErrKeyNotFound   = errors.New("mvcc: key not found")
)

type TxnStatus int
const (
	Active    TxnStatus = iota
	Committed
	Aborted
)

// Version chain node; newest version is the head.
type Version struct {
	commitTS int64
	value    string
	next     *Version // older version
}

type Transaction struct {
	id       int64
	snapshot int64          // snapshot at Begin time (globalTS value)
	writeSet map[string]string
	status   TxnStatus
	store    *MVCCStore
}

type MVCCStore struct {
	mu         sync.Mutex
	globalTS   int64               // monotonic commit-timestamp counter
	txnCounter int64               // monotonic transaction-ID counter
	keys       map[string]*Version // key → head of version chain
	activeTxns map[int64]*Transaction
	watermark  int64               // min snapshot of active txns (for GC)
}

func New() *MVCCStore {
	return &MVCCStore{
		globalTS:   0,
		txnCounter: 0,
		keys:       make(map[string]*Version),
		activeTxns: make(map[int64]*Transaction),
	}
}

// Begin assigns a txn ID and records the current globalTS as the snapshot.
func (s *MVCCStore) Begin() *Transaction {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.txnCounter++
	id := s.txnCounter
	snapshot := s.globalTS
	txn := &Transaction{
		id: id, snapshot: snapshot,
		writeSet: make(map[string]string),
		status:   Active, store: s,
	}
	s.activeTxns[id] = txn
	s.updateWatermark()
	return txn
}

// Get reads from the txn's write set first (read-your-writes),
// then walks the version chain for the newest version with commitTS ≤ snapshot.
func (txn *Transaction) Get(key string) (string, error) {
	txn.store.mu.Lock()
	defer txn.store.mu.Unlock()
	if txn.status != Active {
		return "", ErrAborted
	}
	if val, ok := txn.writeSet[key]; ok {
		return val, nil
	}
	head, exists := txn.store.keys[key]
	if !exists {
		return "", ErrKeyNotFound
	}
	for v := head; v != nil; v = v.next {
		if v.commitTS <= txn.snapshot {
			return v.value, nil
		}
	}
	return "", ErrKeyNotFound
}

// Put stages the write in the txn's write set (not visible until Commit).
func (txn *Transaction) Put(key, value string) error {
	txn.store.mu.Lock()
	defer txn.store.mu.Unlock()
	if txn.status != Active {
		return ErrAborted
	}
	txn.writeSet[key] = value
	return nil
}

// Commit uses first-committer-wins: if any concurrent txn (commitTS > our snapshot)
// already wrote to the same key, we abort with ErrWriteConflict.
func (txn *Transaction) Commit() error {
	txn.store.mu.Lock()
	defer txn.store.mu.Unlock()
	if txn.status != Active {
		if txn.status == Aborted { return ErrAborted }
		return ErrCommitted
	}
	// Conflict detection: check each write-set key for a concurrent committed version
	for key := range txn.writeSet {
		head, exists := txn.store.keys[key]
		if !exists { continue }
		if head.commitTS > txn.snapshot {
			txn.status = Aborted
			delete(txn.store.activeTxns, txn.id)
			txn.store.updateWatermark()
			return ErrWriteConflict
		}
	}
	// Assign commit timestamp and materialize versions
	txn.store.globalTS++
	commitTS := txn.store.globalTS
	for key, val := range txn.writeSet {
		txn.store.keys[key] = &Version{
			commitTS: commitTS,
			value:    val,
			next:     txn.store.keys[key],
		}
	}
	txn.status = Committed
	delete(txn.store.activeTxns, txn.id)
	txn.store.updateWatermark()
	txn.store.gc()
	return nil
}

func (txn *Transaction) Abort() {
	txn.store.mu.Lock()
	defer txn.store.mu.Unlock()
	if txn.status != Active { return }
	txn.status = Aborted
	delete(txn.store.activeTxns, txn.id)
	txn.store.updateWatermark()
}

// updateWatermark recalcs the min snapshot across active transactions.
func (s *MVCCStore) updateWatermark() {
	minSnapshot := s.globalTS
	for _, txn := range s.activeTxns {
		if txn.snapshot < minSnapshot {
			minSnapshot = txn.snapshot
		}
	}
	s.watermark = minSnapshot
}

// gc removes versions with commitTS < watermark (invisible to all active txns),
// keeping at least the boundary version so the chain isn't broken.
func (s *MVCCStore) gc() {
	if len(s.activeTxns) == 0 {
		for key, head := range s.keys {
			if head != nil { head.next = nil; s.keys[key] = head }
		}
		return
	}
	for key, head := range s.keys {
		if head == nil { continue }
		var prev *Version
		for v := head; v != nil; v = v.next {
			if v.commitTS < s.watermark {
				if prev != nil { prev.next = v.next } else { head = v.next }
			} else {
				prev = v
			}
		}
		s.keys[key] = head
	}
}
```

### Key Design Decisions

| Concept | Implementation |
|---|---|
| **Version chain** | Singly-linked list per key; newest version is the head. Each node stores `commitTS` and `value`. |
| **Snapshot** | Captured at `Begin` as the current value of `globalTS`. A transaction sees only versions with `commitTS ≤ snapshot`. |
| **Read-your-writes** | `Get` checks `writeSet` before walking the version chain. |
| **Write-write conflict** | "First committer wins": at `Commit`, for each key in the write set, if the latest committed version has `commitTS > snapshot` (a concurrent txn committed first), abort with `ErrWriteConflict`. |
| **Garbage collection** | `watermark` = minimum snapshot across all active transactions. Versions with `commitTS < watermark` are invisible to all active txns and are pruned. |

