def _alpha(m):
    """Return the alpha_m constant for bias correction of m registers."""
    if m == 16:
        return 0.673
    if m == 32:
        return 0.697
    if m == 64:
        return 0.709
    return 0.7213 / (1.0 + 1.079 / m)


def _hash_64(item):
    """Return a well-mixed 64-bit hash of *item* using the first 8 bytes
    of SHA-256.  Accepts strings, bytes, or any object convertible via str()."""
    if isinstance(item, str):
        data = item.encode("utf-8")
    elif isinstance(item, bytes):
        data = item
    else:
        data = str(item).encode("utf-8")
    return struct.unpack(">Q", sha256(data).digest()[:8])[0]


def _register_index_and_value(hash_val, p):
    """Split a 64-bit hash into (register_index, ρ-value).

    The first *p* most-significant bits select the register.
    The remaining 64-p bits are used to compute ρ = number-of-leading-zeros + 1.
    Returns (index, rho).
    """
    idx = hash_val >> (64 - p)
    remaining = hash_val & ((1 << (64 - p)) - 1)

    if remaining == 0:
        rho = 64 - p + 1
    else:
        leading_zeros = (64 - p) - remaining.bit_length()
        rho = leading_zeros + 1

    return idx, rho


class HyperLogLogPlusPlus:
    """Encapsulates the HLL++ estimation logic."""

    def __init__(self, p=14, sparse_threshold=None):
        if p < 4 or p > 18:
            raise ValueError(f"precision p must be in [4, 18], got {p}")
        self.p = p
        self.m = 1 << p

        self._sparse = []         # sorted list of (index, rho) tuples
        self._registers = None    # dense register array (None when sparse)

        if sparse_threshold is None:
            self.sparse_threshold = self.m
        else:
            self.sparse_threshold = sparse_threshold

    # -- public api ---------------------------------------------------------

    def add(self, item):
        h = _hash_64(item)
        idx, rho = _register_index_and_value(h, self.p)

        if self._registers is not None:
            if rho > self._registers[idx]:
                self._registers[idx] = rho
        else:
            self._add_to_sparse(idx, rho)

    def cardinality(self):
        if self._registers is not None:
            return self._estimate_dense()
        return self._estimate_sparse()

    def merge(self, other):
        if self.p != other.p:
            raise ValueError(
                f"Cannot merge HLLs with different precision "
                f"({self.p} vs {other.p})"
            )
        if other._registers is None:
            other._promote_to_dense()
        if self._registers is None:
            self._promote_to_dense()

        for i in range(self.m):
            if other._registers[i] > self._registers[i]:
                self._registers[i] = other._registers[i]

    # -- sparse internals ---------------------------------------------------

    def _add_to_sparse(self, idx, rho):
        lo, hi = 0, len(self._sparse)
        while lo < hi:
            mid = (lo + hi) // 2
            mid_idx = self._sparse[mid][0]
            if mid_idx < idx:
                lo = mid + 1
            elif mid_idx > idx:
                hi = mid
            else:
                if rho > self._sparse[mid][1]:
                    self._sparse[mid] = (idx, rho)
                return
        self._sparse.insert(lo, (idx, rho))
        if len(self._sparse) >= self.sparse_threshold:
            self._promote_to_dense()

    def _promote_to_dense(self):
        self._registers = [0] * self.m
        for idx, rho in self._sparse:
            if rho > self._registers[idx]:
                self._registers[idx] = rho
        self._sparse = None

    # -- sparse estimation --------------------------------------------------

    def _estimate_sparse(self):
        if not self._sparse:
            return 0.0

        k = len(self._sparse)

        # Linear counting when few registers have been seen
        if k <= self.m // 3:
            v = self.m - k
            return self.m * math.log(self.m / v)

        # HLL harmonic-mean formula from sparse data
        return self._estimate_sparse_via_hll()

    def _estimate_sparse_via_hll(self):
        alpha = _alpha(self.m)
        sum_inv = 0.0
        sp_idx = 0
        for reg in range(self.m):
            if sp_idx < len(self._sparse) and self._sparse[sp_idx][0] == reg:
                val = self._sparse[sp_idx][1]
                sp_idx += 1
            else:
                val = 0
            sum_inv += 1.0 / (1 << val)

        raw = alpha * self.m * self.m / sum_inv

        if raw <= 5 * self.m:
            zeros = self.m - len(self._sparse)
            bias_corrected = self._apply_bias_correction(raw)
            if zeros > 0:
                linear_count = self.m * math.log(self.m / zeros)
                if linear_count < bias_corrected:
                    return linear_count
            return bias_corrected
        return raw

    # -- dense estimation ---------------------------------------------------

    def _estimate_dense(self):
        alpha = _alpha(self.m)
        sum_inv = 0.0
        zeros = 0

        for val in self._registers:
            if val == 0:
                zeros += 1
            sum_inv += 1.0 / (1 << val)

        raw_estimate = alpha * self.m * self.m / sum_inv

        linear_count = None
        if zeros > 0:
            linear_count = self.m * math.log(self.m / zeros)

        if raw_estimate <= 5 * self.m:
            bias_corrected = self._apply_bias_correction(raw_estimate)
            if linear_count is not None and linear_count < bias_corrected:
                return linear_count
            return bias_corrected

        return raw_estimate

    # -- bias correction ----------------------------------------------------

    def _apply_bias_correction(self, raw_estimate):
        table = _BIAS_14 if self.p == 14 else self._generate_bias_table()
        if not table:
            return raw_estimate

        if raw_estimate <= table[0][0]:
            return raw_estimate - table[0][1]
        if raw_estimate >= table[-1][0]:
            return raw_estimate - table[-1][1]

        lo, hi = 0, len(table) - 1
        while lo < hi - 1:
            mid = (lo + hi) // 2
            if table[mid][0] <= raw_estimate:
                lo = mid
            else:
                hi = mid

        x0, b0 = table[lo]
        x1, b1 = table[hi]
        frac = (raw_estimate - x0) / (x1 - x0) if x1 != x0 else 0
        bias = b0 + frac * (b1 - b0)
        return raw_estimate - bias

    @staticmethod
    def _generate_bias_table():
        return []


class HyperLogLogPlusPlusCardinality:
    """Public wrapper satisfying the hyperloglog-plusplus-cardinality interface."""

    def __init__(self, p=14, sparse_threshold=None):
        self._hll = HyperLogLogPlusPlus(p, sparse_threshold)

    def add(self, item):
        self._hll.add(item)

    def cardinality(self):
        return self._hll.cardinality()

    def merge(self, other):
        if isinstance(other, HyperLogLogPlusPlusCardinality):
            self._hll.merge(other._hll)
        else:
            self._hll.merge(other)
```

**Key design decisions:**

| Component | Approach |
|-----------|----------|
| **64-bit hash mixing** | First 8 bytes of SHA-256, unpacked as unsigned 64-bit big-endian integer — well-mixed and deterministic |
| **Register splitting** | Top `p` bits → register index; remaining `64-p` bits → `ρ` = leading-zeros + 1 |
| **Sparse representation** | Sorted list of deduplicated `(index, ρ)` pairs; binary-search insertion keeps O(log k) |
| **Promotion threshold** | Configurable; default `m` (all registers observed). When `len(_sparse) >= threshold`, converts to dense array |
| **Sparse estimation** | Linear counting (`m·ln(m/v)`) when `< m/3` registers seen; HLL harmonic-mean formula otherwise |
| **Dense estimation** | HLL harmonic-mean → bias correction (interpolated table) → linear-counting fallback |
| **Bias correction** | Precomputed table for p=14; linear interpolation between entries; applied when `raw ≤ 5m` (intermediate range) |
| **Linear fallback** | If `linear_count < bias_corrected`, the smaller (more conservative) estimate is used |

